"use strict";(self.webpackChunkliquidflashcards_docs=self.webpackChunkliquidflashcards_docs||[]).push([[1218],{8239(e){e.exports=JSON.parse('{"tag":{"label":"data","permalink":"/liquidflashcards-docs/decisions/tags/data","allTagsPath":"/liquidflashcards-docs/decisions/tags","count":3,"items":[{"id":"0001-one-global-card-library","title":"ADR 0001: One global card library with deck links","description":"Cards belong to the profile, not to a deck; decks reference them through a many-to-many DeckCardLink, and each card keeps one review schedule.","permalink":"/liquidflashcards-docs/decisions/0001-one-global-card-library"},{"id":"0003-swiftdata-with-opt-in-cloudkit","title":"ADR 0003: SwiftData with opt-in CloudKit mirroring and versioned schemas","description":"All data lives in one SwiftData store that mirrors to the iCloud private database only when the user turns sync on; schema changes go through AppSchemaVn versions and the store is never deleted while it holds data.","permalink":"/liquidflashcards-docs/decisions/0003-swiftdata-with-opt-in-cloudkit"},{"id":"0004-profile-delete-keeps-content","title":"ADR 0004: Deleting a profile nullifies its decks and cards","description":"Profile.decks and Profile.cards use a nullify delete rule, and startup maintenance adopts profile-less decks and cards, so a synced profile merge can\'t delete another device\'s offline content.","permalink":"/liquidflashcards-docs/decisions/0004-profile-delete-keeps-content"}],"unlisted":false}}')}}]);